INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('srpwsrp7l2ow9a6926mt4x6srpwsrlo0', '2025-Q2', 'Jun/2025', '2025-06-13T14:44'::timestamptz, 'Marcelo Ribeiro Donatao', 'marcelo ribeiro donatao', 'PHARUS', 'Junior Teixeira', 3.0, 'Detrator', 9.0, NULL, NULL, NULL, NULL, NULL, 'Desacreditei do método', 'Entendi o método, mas ainda não implementei o suficiente', 'Pela propaganda nas redes sociais, eu esperava um acompanhamento mais detalhado. Da minha experiência, como cliente paguei caro por algo que muitos nem cobram. Do que levei até o momento, meu assessor da XP entrega. Escritórios de investimentos e alavancagem patrimonial também entregam. Quando entrei no programa a minha expectativa, talvez equivocada, era ter algo no financeiro, similar a um personal trainner, que acompanha seu mentorado, com lupa. Tanto é que depois deu reclamar dos serviços prestados mudaram meu consultor. Melhorou mais ainda a quem do que eu esperava receber e nada contra o assessor mas sim os serviços oferecidos. Basicamente tenho utilizado estas consultorias para confirmar as estratégias que acredito ser a mais viável para minha situação. Reitero, isto no mercado encontro sem custo. Para mim o ROI com a Pharus esta bem deficitário.', 'Insights que não vislumbrei, serviços detalhado de acompanhamento, tanto de construção patrimonial quanto de melhores práticas para se desendividar. Para mim é muita teoria e pouca prática.', NULL, 'Me apresentar de forma clara, objetiva e estruturada o passo a passo e acompanhamento com metas e objetivos bem como os mecanismos necessários para se atingir o objetivo almejado.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', 'srpwsrp7l2ow9a6926mt4x6srpwsrlo0', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
