INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('ezhl5ej2cno5gezqqnpyfb4i1gjrigqq', '2025-Q2', 'Jun/2025', '2025-06-13T18:04'::timestamptz, 'Denis Heringer', 'denis heringer', 'PHARUS', 'Rafael Pracz', 5.0, 'Detrator', 5.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', 'Por enquanto o meu maior motivo de ter ingressado no programa nao foi atendido pelo meu estrategista. Fui apresentado varias estratégias, que pretendo implementa-las com certeza, porem o que eu gostaria de auxilio do meu estrategista, não obtive até então.', 'Acredito que foco maior no que eu havia pedido, me pareceu que as estratégias sao “fixas”,  a communicacao com o estrategista pode melhorar.', NULL, 'Um atendimento mais personalizado, quando entrei no programa, eu mencionei que sentiria que teria valido a pena caso trabalhassemos nos pontos que mencionei, mas confesso que fiquei um pouco decepcionado quando meu estrategista me apresentou o plano, pois nao incluia os principais pontos que eu havia mencionado no começo. Ainda assim, gostei do que foi apresentado, pretendo implementar todos os pontos o mais rapido possivel.', NULL, NULL, NULL, 'v2025-jun', 'NPS_06_2025.xlsx', 'NPS (PHARUS)', 'ezhl5ej2cno5gezqqnpyfb4i1gjrigqq', 'aba PHARUS da planilha', 'própria resposta') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
